css:
.d-grid-light{display:inline-flex;flex-direction:column;gap:var(--sp-8);font-family:var(--sans);outline:none;cursor:crosshair}
.d-gl-grid{display:grid;grid-template-columns:repeat(12,22px);grid-auto-rows:22px;gap:1px;width:max-content;background:var(--line);border:1px solid var(--line)}
.d-gl-cell{background:var(--paper);transition:background 180ms steps(6),opacity 180ms steps(6)}
.d-gl-cell.is-l1{background:#c2402a}
.d-gl-cell.is-l2{background:#c2402a;opacity:.5}
.d-gl-cell.is-l3{background:#c2402a;opacity:.22}
.d-gl-tip{font-family:var(--mono);font-size:var(--fs-9);letter-spacing:.08em;color:var(--faint)}
.d-grid-light:focus-visible{outline:1px solid var(--ink);outline-offset:4px}

init:
root => {
  const box = root.querySelector('.d-grid-light');
  if (!box || box.dataset.dgl) return;
  box.dataset.dgl = '1';
  const grid = box.querySelector('.d-gl-grid');
  const cols = 12, rows = 5, step = 23;
  if (!grid.children.length) {
    for (let i = 0; i < cols * rows; i++) {
      const cell = document.createElement('span');
      cell.className = 'd-gl-cell';
      grid.appendChild(cell);
    }
  }
  const cells = [...grid.children];
  let at = -1, kx = 5, ky = 2;
  const clear = () => { cells.forEach(c => { c.className = 'd-gl-cell'; }); at = -1; };
  const paint = (col, row) => {
    if (col < 0 || row < 0 || col >= cols || row >= rows) { clear(); return; }
    const idx = row * cols + col;
    if (idx === at) return;
    at = idx;
    cells.forEach((c, i) => {
      const d = Math.hypot(i % cols - col, Math.floor(i / cols) - row);
      c.className = 'd-gl-cell' + (d <= 1 ? ' is-l1' : d <= 2.2 ? ' is-l2' : d <= 3.2 ? ' is-l3' : '');
    });
  };
  const atPointer = e => {
    const r = grid.getBoundingClientRect();
    kx = Math.floor((e.clientX - r.left) / step);
    ky = Math.floor((e.clientY - r.top) / step);
    paint(kx, ky);
  };
  grid.addEventListener('pointermove', atPointer);
  grid.addEventListener('pointerdown', atPointer);
  grid.addEventListener('pointerleave', clear);
  box.addEventListener('focus', () => paint(kx, ky));
  box.addEventListener('blur', clear);
  box.addEventListener('keydown', e => {
    const k = e.key;
    if (k === 'ArrowLeft' || k === 'ArrowRight' || k === 'ArrowUp' || k === 'ArrowDown') {
      e.preventDefault();
      kx = Math.max(0, Math.min(cols - 1, kx + (k === 'ArrowRight' ? 1 : k === 'ArrowLeft' ? -1 : 0)));
      ky = Math.max(0, Math.min(rows - 1, ky + (k === 'ArrowDown' ? 1 : k === 'ArrowUp' ? -1 : 0)));
      paint(kx, ky);
    } else if (k === 'Escape') { clear(); }
  });
}
